// The 7 PlacidWay source URLs shared in the assessment brief.
// Only these pages may be used as the bot's knowledge.
return [
  { json: { name: 'profile', url: 'https://www.placidway.com/profile/5/Alternative-Cancer-Treatment-by-ITC-Immunity-Therapy-Center' } },
  { json: { name: 'package_adenocarcinoma', url: 'https://www.placidway.com/package/7903/Alternative-Adenocarcinoma-Cancer-Treatment-Package-in-Tijuana-Mexico-by-ITC' } },
  { json: { name: 'package_adrenal', url: 'https://www.placidway.com/package/7902/Alternative-Adrenal-Cancer-Treatment-Package-in-Tijuana-Mexico-by-ITC' } },
  { json: { name: 'package_anal', url: 'https://www.placidway.com/package/7901/Alternative-Anal-Cancer-Treatment-Package-in-Tijuana-Mexico-by-ITC' } },
  { json: { name: 'videos', url: 'https://www.placidway.com/profile-videos/5/Alternative-Cancer-Treatment-by-ITC-Immunity-Therapy-Center' } },
  { json: { name: 'price_list', url: 'https://www.placidway.com/price-list/5/Alternative-Cancer-Treatment-by-ITC-Immunity-Therapy-Center' } },
  { json: { name: 'search_pricings', url: 'https://www.placidway.com/search-medical-pricings/Alternative-Medicine/All/1' } }
];

// Clean HTML -> plain text -> ~700 char chunks. Keeps source name+url on every chunk.
const { name, url, data } = $input.first().json;
let html = String(data || '');
html = html.replace(/<script[\s\S]*?<\/script>/gi, '\n').replace(/<style[\s\S]*?<\/style>/gi, '\n');
let text = html.replace(/<[^>]+>/g, '\n');
text = text.replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>');
const junk = /cookie|privacy policy|terms of|all rights reserved|newsletter|subscribe now/i;
const seen = new Set();
const lines = [];
for (const raw of text.split('\n')) {
  const l = raw.replace(/\s+/g, ' ').trim();
  if (l.length > 40 && !junk.test(l) && !seen.has(l)) { seen.add(l); lines.push(l); }
}
const chunks = [];
let cur = '';
for (const l of lines) {
  if ((cur + ' ' + l).length > 700 && cur) { chunks.push(cur); cur = l; }
  else { cur = cur ? cur + ' ' + l : l; }
}
if (cur) chunks.push(cur);
return chunks.map(c => ({ json: { text: c, source_name: name, source_url: url } }));
